/* TA Learning Hub — shared record model, linked views and drill-downs. */
const HUB_SKILLS=[...NAMES]; // Exact English competency names from FOLLOW 2026!J7:O7.
const HUB_DESC=['เข้าใจลูกค้า สร้างความสัมพันธ์ และส่งมอบคุณค่า','ต่อยอดความคิด พัฒนางานให้ดียิ่งขึ้น','ใช้ทรัพยากรอย่างคุ้มค่า สร้างผลลัพธ์ที่ยั่งยืน','ใช้ข้อมูลขับเคลื่อนงาน และพัฒนาทักษะดิจิทัล','เสริมความเชี่ยวชาญให้พร้อมกับบทบาทงาน','ยกระดับมาตรฐานและความน่าเชื่อถือของงาน'];
const HUB_COLORS=['#ee967a','#e8b44a','#73bd94','#72a8df','#ad8ad4','#57adaf'];
const HUB_MENU=[['overview','grid','ภาพรวม'],['learning','book','เส้นทางการเรียนรู้'],['followup','target','แผนพัฒนาทักษะ'],['reports','chart','รายงาน'],['directory','tracking','ติดตามผลรายบุคคล'],['peopleDB','users','ตั้งค่าบุคลากรและบันทึกผล']];
TABS.splice(0,TABS.length,...HUB_MENU.map(x=>[...x,x[2]]),['guide','info','คู่มือและหลักเกณฑ์','Guide'],['directory','users','รายชื่อในฐานติดตาม','People'],['matrix','layers','แผนที่สมรรถนะ','Matrix'],['upskill','book','Upskilling','Learning']);
let hubFocus=null,hubStatus='pending',hubPage=0,hubDrillSearch='',hubDomain='core',hubProfileId='';
const hubLegacyRender=renderContent,hubLegacyExport=exportData;
const hubGraphic=(i,cls='')=>`<span aria-hidden="true" class="hub-graphic ${cls}" style="--sprite-x:${(i%3)*50}%;--sprite-y:${Math.floor(i/3)*100}%"></span>`;
// Each different content topic owns a distinct 3D illustration.
const HUB_ART = Object.freeze({overview:[0,1,2,3],followup:[4,5,6,7],upskill:[8,9,10,11,12,13],help:14,priority:15,group:[16,17,18],reports:[19,20,21,22]});
const hubTopicGraphic=(i,cls='')=>`<span aria-hidden="true" data-art-topic="${i}" class="hub-graphic hub-topic-graphic ${cls}" style="--sprite-x:${(i%5)*25}%;--sprite-y:${Math.floor(i/5)*25}%"></span>`;
const hubSkillGraphic=(kind,i)=>kind==='up'?hubTopicGraphic(HUB_ART.upskill[i%HUB_ART.upskill.length]):hubGraphic(i);

function hubPlan(v){const p=parseStatus(v);return !done(v)&&p.plan&&(!p.year||p.year<=+year);}
function hubSkillPeople(kind,index){const arr=selectData(kind==='up'?ups:records);return arr.map(e=>{const a=evaluate(e),required=kind==='up'?(!!String(e.cells[index]||'').trim()&&(!parseStatus(e.cells[index]).year||parseStatus(e.cells[index]).year<=+year)):a.req.includes(index+1),complete=done(e.cells[index]),planned=hubPlan(e.cells[index]);return{e,required,complete,planned,kind:kind==='up'?'Upskilling':a.must.includes(index+1)?'Must Have':a.should.includes(index+1)?'Should Have':'เสริมทักษะ'};});}
function hubSkillSummary(kind,index){const people=hubSkillPeople(kind,index),eligible=people.filter(x=>x.required),complete=eligible.filter(x=>x.complete).length,planned=eligible.filter(x=>x.planned).length;return{people,eligible:eligible.length,complete,planned,pending:eligible.length-complete,unplanned:eligible.length-complete-planned,pct:eligible.length?complete/eligible.length*100:0};}
function hubRegistry(){return records.filter(e=>(!lab||e.lab===lab)&&(!pl||e.pl===pl)&&(!query||`${e.firstName} ${e.lastName} ${e.title} ${e.lab} ${e.functionName}`.toLowerCase().includes(query.toLowerCase())));}
function hubTitle(){if(['directory','matrix'].includes(tab))return 'ติดตามผลรายบุคคล';return HUB_MENU.find(x=>x[0]===tab)?.[2]||TABS.find(x=>x[0]===tab)?.[2]||'Learning Hub';}
shell=function(){const title=hubTitle(),readonly=dbState.access?.role==='viewer';$('#app').innerHTML=`<div class="mobile-overlay" data-action="menu"></div><aside><button class="hub-brand" data-tab="overview" aria-label="TA Learning Hub หน้าหลัก"><span class="hub-logo">${icon('network')}</span><span>TA<strong>Learning Hub</strong></span></button><nav>${HUB_MENU.filter(m=>!(readonly&&m[0]==='input')).map(m=>`<button data-tab="${m[0]}" class="${(tab===m[0]||(tab==='matrix'&&m[0]==='directory'))?'active':''}">${icon(m[1])}<span>${m[2]}</span></button>`).join('')}</nav><div class="hub-help"><span class="help-art">${hubTopicGraphic(HUB_ART.help)}</span><strong>คำถามหรือ<br>ต้องการความช่วยเหลือ?</strong><p>วิธีใช้งาน เกณฑ์ทักษะ<br>และการเชื่อมข้อมูล</p><button data-tab="guide">เปิดคู่มือ ${icon('arrow')}</button></div><button class="hub-account" data-hub="account"><span class="avatar">TA</span><span><small>${window.TA_CLOUD?.enabled?'ผู้ใช้งาน':'เวอร์ชันทดลอง'}</small><strong>${esc(dbState.access?.label||'ทีมพัฒนาทักษะ')}</strong></span>${icon('info')}</button></aside><main><header class="hub-header"><div class="hub-page-heading"><button class="menu-btn" data-action="menu" aria-label="เปิดเมนู">${icon('menu')}</button><div><h1>${esc(title==='ภาพรวม'?'ภาพรวมการพัฒนาทักษะ':title)}</h1><p><button data-tab="overview">หน้าหลัก</button><span>›</span>${esc(title)}</p></div></div><div class="hub-controls"><label class="hub-global-search">${icon('search')}<input id="hub-global-search" placeholder="ค้นหาบุคลากร หรือ BU..." aria-label="ค้นหาบุคลากรหรือ BU" value="${esc(query)}"></label><select id="lab" aria-label="กรอง BU">${options(records.map(e=>e.lab),lab,'ทุก BU')}</select><select id="year" aria-label="กรองปีสะสม"><option value="2026" ${year==='2026'?'selected':''}>2026</option><option value="2025" ${year==='2025'?'selected':''}>2025</option></select><button class="hub-clear-filter filter-reset" data-hub="reset" title="ล้างคำค้นหา BU และระดับ PL" ${query||lab||pl?'':'disabled'}><span class="filter-reset-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></span><span>ล้างตัวกรอง</span></button><button class="hub-notice" data-hub="pending" aria-label="ดูรายการพัฒนาที่ค้าง">${icon('clock')}<span></span></button>${readonly?'':`<button class="btn primary" data-tab="peopleDB">รายชื่อ / บันทึกผล</button>`}</div></header>${window.TA_CLOUD?.enabled?`<div class="hub-source online"><span class="dot"></span>ฐานกลาง Google Sheets · ${esc(loadedAt)}<button data-action="refresh">อ่านข้อมูลล่าสุด</button></div>`:`<div class="hub-source"><span class="dot"></span>ข้อมูลจาก Excel ที่ให้มา · บันทึกในอุปกรณ์นี้<button data-hub="connection">ตั้งค่าฐานข้อมูลกลาง</button></div>`}<div id="content"></div><footer class="hub-footer"><span>TA Learning Hub · เรียนรู้ พัฒนา เติบโตไปด้วยกัน</span><button data-tab="guide">ที่มาข้อมูลและหลักเกณฑ์</button><span>${window.TA_CLOUD?.enabled?'Google Sheets กลาง':'ข้อมูลทดลองในเครื่อง'}</span></footer></main>`;renderContent();bindShell();$('#hub-global-search')?.addEventListener('input',e=>{query=e.target.value;hubPage=0;renderContent();const clear=document.querySelector('.hub-clear-filter');if(clear)clear.disabled=!(query||lab||pl);});};
function hubMetric(title,value,unit,i,action,note){return `<button class="hub-metric metric-${i}" data-hub="${action}">${hubTopicGraphic((tab==='reports'?HUB_ART.reports:HUB_ART.overview)[i])}<span class="hub-metric-copy"><strong>${title}</strong><span class="metric-number">${value}<small>${unit}</small></span><span class="metric-note">${note}</span></span></button>`;}
function hubSkillCard(i,kind='core'){const s=hubSkillSummary(kind,i),name=kind==='core'?HUB_SKILLS[i]:upNames()[i];return `<button class="hub-skill-card" data-hub-skill="${i}" data-domain="${kind}" style="--skill-color:${HUB_COLORS[i%HUB_COLORS.length]}">${hubSkillGraphic(kind,i)}<span class="skill-copy"><strong>${esc(name)}</strong><small>${kind==='core'?HUB_DESC[i]:'หลักสูตรเสริมทักษะจาก Upskilling 2026'}</small><span class="skill-progress"><span class="track"><i style="width:${s.pct}%"></i></span><b>${s.eligible?pct(s.pct)+'%':'—'}</b></span><span class="skill-link">สำเร็จ ${s.complete} · ${kind==='core'?'ยังขาด':'มีแผน'} ${kind==='core'?s.pending:s.planned} คน ${icon('arrow')}</span></span></button>`;}
function hubOverview(){const arr=selectData(),a=aggregate(arr),reg=hubRegistry(),priorities=HUB_SKILLS.map((n,i)=>({name:n,i,...hubSkillSummary('core',i)})).filter(x=>x.pending).sort((a,b)=>b.pending-a.pending).slice(0,3);return `<section class="hub-hero"><div class="hub-hero-art" role="img" aria-label="คนเรียนรู้ร่วมกันและเส้นทางการเติบโต"></div><div class="hub-hero-copy"><h2>เติมทักษะใหม่<br><span>เติบโตไปด้วยกัน</span></h2><p>เชื่อมทุกโอกาสการเรียนรู้ สู่การพัฒนาที่ตรงจุด</p><div class="hero-ctas"><button class="btn primary" data-tab="learning">สำรวจเส้นทางการเรียนรู้ ${icon('arrow')}</button><button class="hub-text-btn" data-tab="followup">ดูแผนพัฒนาของทีม ${icon('arrow')}</button></div></div></section><div class="hub-metrics">${hubMetric('บุคลากรในทะเบียน',reg.length,'คน',0,'registry',`${a.people} คนอยู่ในฐานติดตาม`)}${hubMetric('ทักษะหลัก',6,'ด้าน',1,'skills','เชื่อมทุกบทบาทและระดับ PL')}${hubMetric('ความก้าวหน้าตามเกณฑ์',pct(a.pct),'%',2,'reports',`${a.complete} / ${a.total} รายการ`)}${hubMetric('รอพัฒนาต่อ',a.pending,'คน',3,'pending',`${a.remaining} รายการสมรรถนะคงเหลือ`)}</div><div class="hub-home-grid"><section><div class="hub-section-heading"><div><h2>พัฒนาทักษะรอบด้าน</h2><p>ทักษะที่จำเป็น เพื่อการเติบโตของบุคลากรและองค์กร</p></div><button data-tab="learning">ดูทั้งหมด ${icon('arrow')}</button></div><div class="hub-skills-grid">${HUB_SKILLS.map((n,i)=>hubSkillCard(i)).join('')}</div></section><section class="hub-priorities panel"><div class="hub-priority-title">${hubTopicGraphic(HUB_ART.priority)}<div><h3>โฟกัสการพัฒนาถัดไป</h3><p>เรียงตามจำนวนผู้ที่ยังพัฒนาไม่ครบ</p></div></div>${priorities.map((p,j)=>`<button class="priority-row priority-${j}" data-hub-skill="${p.i}" data-domain="core"><span class="priority-rank">${j+1}</span><span><strong>${p.name}</strong><small>ยังขาด ${p.pending} คน · ${p.unplanned} คนยังไม่มีแผน</small></span>${icon('arrow')}</button>`).join('')||'<div class="hub-congratulations">✓ ทุกคนพัฒนาครบตามเกณฑ์แล้ว</div>'}<button class="priority-bottom" data-tab="followup">เปิดแผนพัฒนาทั้งหมด ${icon('arrow')}</button></section></div><div class="hub-data-note">${icon('info')} ตัวเลขคำนวณจากข้อมูลจริงตามตัวกรอง · เปอร์เซ็นต์นับ Must + Should สะสมถึงปี ${year} · ข้อมูลเดิมมีสถานะบุคลากร 3 รายรอตรวจทาน<button data-tab="guide">ดูรายละเอียด</button></div>`;}
function hubLearning(){if(hubFocus)return hubDrillView();return `<div class="hub-learning-intro"><div><span class="eyebrow">YOUR LEARNING JOURNEY</span><h2>เลือกทักษะที่อยากพัฒนาต่อ</h2><p>ดูความพร้อมของทีม เลือกทักษะเพื่อสำรวจผู้ที่สำเร็จแล้ว ผู้ที่ยังขาด และแผนเรียนรู้รายบุคคล</p></div>${hubGraphic(1)}</div><div class="hub-domain-tabs"><button data-hub-domain="core" aria-pressed="${hubDomain==='core'}" class="${hubDomain==='core'?'active':''}">${icon('layers')} สมรรถนะหลัก 6 ด้าน</button><button data-hub-domain="up" aria-pressed="${hubDomain==='up'}" class="${hubDomain==='up'?'active':''}">${icon('book')} หลักสูตร Upskilling</button></div><div class="hub-skills-grid catalog">${(hubDomain==='core'?HUB_SKILLS:upNames()).map((n,i)=>hubSkillCard(i,hubDomain)).join('')}</div><section class="hub-learning-how"><h3>จากทักษะ สู่การลงมือพัฒนา</h3><div><span>01 <strong>เลือกทักษะ</strong><small>เห็นความพร้อมตามเกณฑ์ PL</small></span><span>02 <strong>ดูบุคลากรและ BU</strong><small>แยกสำเร็จ ยังขาด และมีแผน</small></span><span>03 <strong>อัปเดตการพัฒนา</strong><small>บันทึกปี วันที่ และหลักฐาน</small></span></div></section>`;}
function hubFilterDrill(rows){const q=hubDrillSearch.toLowerCase();return rows.filter(x=>{if(q&&!`${x.e.firstName} ${x.e.lastName} ${x.e.lab} ${x.e.title}`.toLowerCase().includes(q))return false;return hubStatus==='all'?x.required:hubStatus==='done'?x.required&&x.complete:hubStatus==='pending'?x.required&&!x.complete:hubStatus==='plan'?x.required&&x.planned:hubStatus==='noplan'?x.required&&!x.complete&&!x.planned:hubStatus==='extra'?!x.required:true;});}
function hubStatusLabel(x){const raw=x.e.cells[hubFocus.i],p=parseStatus(raw);return x.complete?'สำเร็จ'+(p.year?' '+p.year:''):x.planned?'มีแผน'+(p.year?' '+p.year:''):p.complete?'สำเร็จปี '+p.year+' (นอกช่วงที่เลือก)':p.plan?'แผนปี '+p.year+' (นอกช่วงที่เลือก)':'ยังไม่ระบุ';}
function hubDrillView(){const {kind,i}=hubFocus,s=hubSkillSummary(kind,i),title=kind==='core'?HUB_SKILLS[i]:upNames()[i],rows=hubFilterDrill(s.people),size=printing?10000:12,pages=Math.max(1,Math.ceil(rows.length/size));hubPage=Math.min(hubPage,pages-1);const visible=rows.slice(hubPage*size,(hubPage+1)*size),labs=[...new Set(s.people.filter(x=>x.required).map(x=>x.e.lab))].sort();return `<div class="hub-drill-heading"><button class="hub-back" data-hub="back-skills">← กลับไปเลือกทักษะ</button><div class="hub-focus-title">${hubGraphic(i)}<div><div class="eyebrow">${kind==='core'?'CORE COMPETENCY':'UPSKILLING'} · สะสมถึงปี ${year}</div><h2>${esc(title)}</h2><p>${kind==='core'?esc(NAMES[i])+' · แสดงตามเกณฑ์ Must / Should ของระดับ PL':'นับรายการที่ระบุ Plan หรือ Complete · ช่องว่างหมายถึงยังไม่ระบุ ไม่ถือว่าเป็นข้อบังคับ'}</p></div></div></div><div class="hub-drill-counts">${[['all','ตามเกณฑ์ / มีรายการ',s.eligible],['done','สำเร็จแล้ว',s.complete],['pending',kind==='core'?'ยังขาด':'รอเรียนตามแผน',s.pending],['plan','มีแผน',s.planned],['noplan',kind==='core'?'ยังไม่มีแผน':'ยังไม่ระบุ',kind==='core'?s.unplanned:s.people.length-s.eligible]].map(([key,label,n])=>`<button class="drill-count ${hubStatus===(kind==='up'&&key==='noplan'?'extra':key)?'active':''} count-${key}" data-hub-status="${kind==='up'&&key==='noplan'?'extra':key}"><span>${label}</span><strong>${n}<small>คน</small></strong></button>`).join('')}</div><section class="panel hub-bu-breakdown"><div class="panel-head"><div><h3>เลือกแล็บที่ต้องการดู</h3><p>แล็บที่ยังขาดแสดงก่อน · กดจำนวนเพื่อดูรายชื่อ</p></div>${lab?'<button data-hub="all-bu">ดูทุก BU</button>':''}</div><div class="hub-bu-chips">${[...labs].sort((a,b)=>s.people.filter(x=>x.required&&!x.complete&&x.e.lab===b).length-s.people.filter(x=>x.required&&!x.complete&&x.e.lab===a).length||a.localeCompare(b)).map(l=>{const set=s.people.filter(x=>x.required&&x.e.lab===l),yes=set.filter(x=>x.complete).length;return `<div class="hub-bu-chip ${set.length>yes?'needs-learning':'all-complete'}"><div class="bu-card-heading"><span class="bu-card-icon">${icon('briefcase')}</span><strong>${esc(l)}</strong><span class="bu-card-total">${set.length} คน</span></div><div class="bu-card-progress"><i style="width:${set.length?yes/set.length*100:0}%"></i></div>`+`<button data-hub-bu="${esc(l)}" data-hub-bu-status="done" title="ดูผู้สำเร็จ ${esc(l)}"><span class="dot"></span>สำเร็จ <b>${yes}</b></button><button data-hub-bu="${esc(l)}" data-hub-bu-status="pending" title="ดูผู้ยังขาด ${esc(l)}"><span class="dot waiting"></span>${kind==='core'?'ยังขาด':'มีแผน'} <b>${set.length-yes}</b></button></div>`;}).join('')||'<div class="empty">ไม่มีรายการตามตัวกรองนี้</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>${{all:'บุคลากรทั้งหมดตามเกณฑ์',done:'บุคลากรที่สำเร็จแล้ว',pending:kind==='core'?'บุคลากรที่ยังขาด':'บุคลากรที่รอเรียน',plan:'บุคลากรที่มีแผน',noplan:'บุคลากรที่ยังไม่มีแผน',extra:kind==='core'?'บุคลากรนอกเกณฑ์':'บุคลากรที่ยังไม่ระบุหลักสูตร'}[hubStatus]}</h3><p>${rows.length} คน · ${lab?esc(lab):'ทุก BU'} · คลิกชื่อเพื่อดูผลพัฒนารายบุคคล</p></div><div class="hub-table-actions"><label class="search"><input id="hub-drill-search" value="${esc(hubDrillSearch)}" aria-label="ค้นหารายชื่อในทักษะ" placeholder="ค้นหาชื่อ / BU"></label><button class="btn" data-hub="export-drill">${icon('export')} ส่งออกรายชื่อ</button></div></div><div class="drill-secondary-filter"><button class="chip ${hubStatus==='extra'?'active':''}" data-hub-status="extra">${kind==='core'?'ดูรายชื่อนอกเกณฑ์':'ดูผู้ยังไม่ระบุหลักสูตร'}</button></div><div class="table-wrap"><table><thead><tr><th>บุคลากร</th><th>BU / แล็บ</th><th>PL</th><th>เกณฑ์</th><th>ผลพัฒนา</th><th>อัปเดต</th></tr></thead><tbody>${visible.map(x=>`<tr><td><button class="person-open" data-hub-person="${esc(x.e.id)}"><div class="person"><span class="avatar">${esc(x.e.firstName[0])}</span><span><strong>${esc(x.e.firstName+' '+x.e.lastName)}</strong><small>${esc(x.e.functionName)}</small></span></div></button></td><td>${esc(x.e.lab)}</td><td><span class="pl-tag">${esc(x.e.pl)}</span></td><td>${x.kind}</td><td><span class="status ${x.complete?'done':x.planned?'':'none'}">${esc(hubStatusLabel(x))}</span></td><td><button class="edit-person" data-edit="${esc(x.e.id)}">${icon('edit')} บันทึกผล</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">ไม่มีรายชื่อในสถานะและตัวกรองที่เลือก</div>'}</div><div class="table-footer"><span>แสดง ${rows.length?hubPage*size+1:0}–${Math.min((hubPage+1)*size,rows.length)} จาก ${rows.length} คน</span><div><button data-hub-page="-1" ${hubPage===0?'disabled':''}>←</button> ${hubPage+1} / ${pages} <button data-hub-page="1" ${hubPage>=pages-1?'disabled':''}>→</button></div></div></section>`;}
function hubOpenDrill(i,kind='core',view='pending'){hubFocus={i:Number(i),kind};hubStatus=view;hubPage=0;hubDrillSearch='';tab='learning';shell();window.scrollTo(0,0);}
skillDetail=function(i){hubOpenDrill(i);};
function hubReports(){const arr=selectData(),a=aggregate(arr),labs=[...new Set(arr.map(e=>e.lab))].sort();return `<div class="hub-report-banner"><div><div class="eyebrow">LEARNING IMPACT</div><h2>ทุกความก้าวหน้า มีข้อมูลให้ติดตาม</h2><p>สรุปตาม BU ระดับ PL และทักษะ · คลิกตัวเลขเพื่อเปิดรายชื่อที่อยู่เบื้องหลังผลลัพธ์</p></div><div class="actions"><button class="btn" data-hub="print">${icon('print')} พิมพ์ PDF</button><button class="btn primary" data-hub="export-report">${icon('export')} ส่งออกรายงาน Excel</button></div></div><div class="hub-report-filters"><label class="report-pl-filter ${pl?'is-filtered':''}"><span>ระดับ PL</span> <select id="pl" aria-label="กรองระดับ PL">${options(records.map(e=>e.pl),pl,'ทุก PL')}</select></label><button class="btn" data-tab="matrix">เปิดตารางสมรรถนะรายคน ${icon('arrow')}</button><button class="btn" data-tab="directory">ดูรายชื่อในฐานติดตาม ${icon('users')}</button></div><div class="hub-metrics">${hubMetric('ฐานติดตาม',a.people,'คน',0,'registry',`${a.eligible} คนมีเกณฑ์`)}${hubMetric('สมรรถนะสำเร็จ',a.complete,'รายการ',1,'skills',`จาก ${a.total} รายการตามเกณฑ์`)}${hubMetric('ความก้าวหน้า',pct(a.pct),'%',2,'skills','ผลรวมสำเร็จ ÷ ผลรวมเกณฑ์')}${hubMetric('พัฒนาครบแล้ว',a.finished,'คน',3,'completed','ครบ Must + Should')}</div><section class="panel"><div class="panel-head"><div><h3>ผลพัฒนารายทักษะ</h3><p>จำนวนคนในแต่ละทักษะนับแยกกัน บุคคลหนึ่งอาจอยู่หลายทักษะ</p></div></div><div class="table-wrap"><table><thead><tr><th>ทักษะ</th><th>ตามเกณฑ์</th><th>Complete</th><th>ยังขาด</th><th>มีแผน</th><th>ยังไม่มีแผน</th><th>ความก้าวหน้า</th></tr></thead><tbody>${HUB_SKILLS.map((n,i)=>{const s=hubSkillSummary('core',i);return `<tr><td><button class="hub-report-skill" data-hub-skill="${i}">${hubGraphic(i)}<strong>${n}</strong></button></td>${[['all',s.eligible],['done',s.complete],['pending',s.pending],['plan',s.planned],['noplan',s.unplanned]].map(([st,n])=>`<td><button class="report-number ${st}" data-hub-skill="${i}" data-start-status="${st}">${n}</button></td>`).join('')}<td><div class="mini-progress"><span class="track"><i class="bar" style="width:${s.pct}%"></i></span><b>${s.eligible?pct(s.pct)+'%':'N/A'}</b></div></td></tr>`;}).join('')}</tbody></table></div></section><section class="panel hub-report-labs"><div class="panel-head"><div><h3>ผลพัฒนาแยก BU</h3><p>คลิกชื่อ BU เพื่อเปิดทะเบียนบุคลากร หรือคลิกทักษะเพื่อเจาะรายชื่อใน BU นั้น</p></div></div><div class="table-wrap"><table><thead><tr><th>BU</th><th>บุคลากร</th><th>ครบตามเกณฑ์</th><th>ยังไม่ครบ</th>${SHORT.map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${labs.map(l=>{const set=arr.filter(e=>e.lab===l),b=aggregate(set);return `<tr><td><button class="text-link" data-hub-registry-bu="${esc(l)}">${esc(l)}</button></td><td>${b.people}</td><td><button class="report-number done" data-hub-person-status="done" data-bu-value="${esc(l)}">${b.finished}</button></td><td><button class="report-number pending" data-hub-person-status="pending" data-bu-value="${esc(l)}">${b.pending}</button></td>${HUB_SKILLS.map((n,i)=>{const el=set.filter(e=>evaluate(e).req.includes(i+1)),doneN=el.filter(e=>done(e.cells[i])).length;return `<td><button class="report-number" title="${esc(n)} สำเร็จ ${doneN}/${el.length}" data-hub-bu="${esc(l)}" data-skill-index="${i}" data-hub-bu-status="all">${el.length?Math.round(doneN/el.length*100)+'%':'—'}</button></td>`;}).join('')}</tr>`;}).join('')}</tbody></table></div></section>`;}
function hubProfile(id){const corePerson=records.find(p=>String(p.id)===String(id)),e=corePerson||ups.find(p=>String(p.id)===String(id));if(!e)return;hubProfileId=e.id;const a=corePerson?evaluate(corePerson):{total:0,completed:0,gap:0,pct:0,must:[],should:[]},core=dbState.core.find(p=>String(p.id)===String(id)),u=ups.find(p=>String(p.id)===String(id)),up=dbState.upskill.find(p=>String(p.id)===String(id));const section=(kind,names,cells,details)=>`<h3 class="profile-section-title">${kind==='core'?'สมรรถนะหลัก':'หลักสูตร Upskilling'}</h3>${names.map((n,i)=>{const d=details?.[i]||{},p=parseStatus(cells?.[i]),complete=done(cells?.[i]),rule=kind==='up'?'Upskilling':a.must.includes(i+1)?'Must Have':a.should.includes(i+1)?'Should Have':'เสริมทักษะ';return `<div class="hub-profile-learning"><button data-profile-skill="${i}" data-domain="${kind}">${hubSkillGraphic(kind,i)}<span><strong>${esc(kind==='core'?HUB_SKILLS[i]:n)}</strong><small>${rule} · ต้นฉบับ: ${esc(cells?.[i]||'ยังไม่ระบุ')}</small></span></button><span class="status ${complete?'done':p.plan?'':'none'}">${complete?'สำเร็จ '+(p.year||''):p.plan?'มีแผน '+(p.year||''):'ยังไม่ระบุ'}</span>${d.completedDate||d.evidence||d.note?`<div class="learning-evidence">${d.completedDate?`วันที่สำเร็จ: ${esc(d.completedDate)} `:''}${/^https?:\/\//i.test(d.evidence||'')?`<a href="${esc(d.evidence)}" target="_blank" rel="noopener noreferrer">เปิดหลักฐาน ↗</a>`:''}${d.note?`<span class="source-note-text">${esc(d.note)}</span>`:''}</div>`:''}</div>`;}).join('')}`;$('#detail').innerHTML=`<div class="modal-head"><div><div class="eyebrow">PERSONAL LEARNING PROFILE</div><h2>${esc(e.firstName+' '+e.lastName)}</h2><p>${esc(e.lab)} · ${esc(e.pl)} · ${esc(e.title)}</p></div><button class="close" data-action="close" aria-label="ปิดรายละเอียด">×</button></div><div class="modal-body"><div class="hub-profile-summary"><span><strong>${a.total?pct(a.pct)+'%':'N/A'}</strong> ความก้าวหน้า</span><span>สำเร็จ <b>${a.completed}/${a.total}</b> ตามเกณฑ์</span><span>ยังขาด <b>${a.gap}</b> ทักษะ</span><button class="btn primary" data-profile-edit="${esc(e.id)}">${icon('edit')} อัปเดตผลพัฒนา</button></div>${corePerson?section('core',NAMES,corePerson.cells,core?.details):'<p>ไม่พบข้อมูลสมรรถนะหลักของบุคคลนี้ในฐานติดตาม</p>'}${section('up',upNames(),u?.cells||[],up?.details)}<p class="modal-note source-note-text">${esc(e.profileNote||'')} ${esc(e.remark||'')} · ผลสะสมถึงปี ${year}</p></div>`;$('#detail').showModal();}
detail=hubProfile;
function hubBindContent(){bindContent();$('#hub-drill-search')?.addEventListener('input',e=>{hubDrillSearch=e.target.value;hubPage=0;const at=e.target.selectionStart;renderContent();$('#hub-drill-search').focus();$('#hub-drill-search').setSelectionRange(at,at);});}
renderContent=function(){if(tab==='overview')$('#content').innerHTML=hubOverview();else if(tab==='learning')$('#content').innerHTML=hubLearning();else if(tab==='reports')$('#content').innerHTML=hubReports();else if(['directory','matrix'].includes(tab))$('#content').innerHTML=hubTracking();else{hubLegacyRender();return;}hubBindContent();if(['reports','directory','matrix'].includes(tab))$('#pl')?.addEventListener('change',e=>{pl=e.target.value;renderContent();});};

function hubTracking(){
 const arr=selectData(),a=aggregate(arr),isMatrix=tab==='matrix';
 const rows=arr.filter(e=>{const r=evaluate(e);return status==='all'||status==='done'&&r.total>0&&!r.gap||status==='pending'&&r.gap>0||status==='noplan'&&r.unplanned>0||status==='na'&&!r.total;});
 const cards=[['all','บุคลากรในฐานติดตาม',a.people,'คน',`${a.eligible} คนมีเกณฑ์ Must / Should`,HUB_ART.reports[0]],['done','พัฒนาครบตามเกณฑ์',a.finished,'คน','ครบทั้ง Must Have และ Should Have',HUB_ART.reports[3]],['pending','ยังพัฒนาไม่ครบ',a.pending,'คน',`${a.remaining} รายการสมรรถนะที่ต้องพัฒนาต่อ`,HUB_ART.followup[1]],['na','ไม่มีเกณฑ์ประเมิน',a.people-a.eligible,'คน','แสดง N/A ไม่ถือว่าไม่ผ่าน',HUB_ART.help]];
 let panel=peoplePanel(rows,isMatrix?'ตารางสมรรถนะรายบุคคล':'ภาพรวมผลพัฒนารายบุคคล',isMatrix);
 panel=panel.replace(/<div class="search">[\s\S]*?<\/div>/,'').replace(/<div class="avatar">[\s\S]*?<\/div>/g,'').replace('<table>',`<table class="tracking-table ${isMatrix?'tracking-matrix':'tracking-overview'}">`).replace('<th></th>','').replace(/<td style="color:#b0a0c5">↗<\/td>/g,'');
 panel=panel.replace('</tr></thead>','<th data-table-action="true"></th></tr></thead>').replace(/<tr data-person="([^"]+)">([\s\S]*?)<\/tr>/g,(_,id,cells)=>`<tr data-person="${id}">${cells}<td class="tracking-action"><button type="button" class="tracking-detail" data-person="${id}">${icon('search')}<span>ดูรายละเอียด</span></button></td></tr>`);
 return `<div class="tracking-page"><div class="tracking-intro"><div><h2>เห็นความก้าวหน้าและช่องว่างของแต่ละคน</h2><p>ข้อมูลชุดเดียว ดูได้ทั้งภาพรวมรายคนและสมรรถนะ 6 ด้าน · คลิกชื่อเพื่อดูรายละเอียด</p></div><label class="report-pl-filter"><span>ระดับ PL</span><select id="pl">${options(records.map(e=>e.pl),pl,'ทุก PL')}</select></label></div><div class="tracking-summary">${cards.map(([key,label,value,unit,note,art],i)=>`<button class="tracking-card tone-${i} ${status===key?'active':''}" data-status="${key}" aria-pressed="${status===key}"><span class="tracking-card-icon">${hubTopicGraphic(art||HUB_ART.help)}</span><span><span class="tracking-card-label">${label}</span><strong>${value}<small>${unit}</small></strong><span class="tracking-card-note">${note}</span></span></button>`).join('')}</div><div class="hub-domain-tabs tracking-tabs" role="group" aria-label="มุมมองผลพัฒนารายบุคคล"><button data-tracking-view="directory" class="${!isMatrix?'active':''}" aria-pressed="${!isMatrix}">${icon('users')} ภาพรวมรายบุคคล</button><button data-tracking-view="matrix" class="${isMatrix?'active':''}" aria-pressed="${isMatrix}">${icon('layers')} ตารางสมรรถนะ</button></div>${panel}</div>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tracking-view]');if(b){tab=b.dataset.trackingView;page=0;renderContent();}});

function hubDownloadWorkbook(sheets,name){if(typeof XLSX==='undefined')throw Error('ตัวอ่าน Excel ยังไม่พร้อม');const wb=XLSX.utils.book_new();for(const [label,rows] of sheets)XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),label);const url=URL.createObjectURL(new Blob([XLSX.write(wb,{bookType:'xlsx',type:'array'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('เตรียมไฟล์ Excel ตามตัวกรองแล้ว');}
function hubExportDrill(){if(!hubFocus)return;const {kind,i}=hubFocus,s=hubSkillSummary(kind,i),rows=hubFilterDrill(s.people).map(x=>({'ชื่อ':x.e.firstName,'นามสกุล':x.e.lastName,'BU':x.e.lab,'PL':x.e.pl,'สายงาน':x.e.functionName,'ทักษะ':kind==='core'?NAMES[i]:upNames()[i],'เกณฑ์':x.kind,'สถานะ':hubStatusLabel(x),'ข้อความต้นฉบับ':x.e.cells[i]||'','ผลสะสมถึงปี':+year}));hubDownloadWorkbook([['รายชื่อรายทักษะ',rows]],`TA_Learning_${kind}_${i+1}_${hubStatus}_${year}.xlsx`);}
function hubExportReport(){const arr=selectData(),a=aggregate(arr),labs=[...new Set(arr.map(e=>e.lab))];hubDownloadWorkbook([['สรุป',[{'ปี':+year,'BU':lab||'ทั้งหมด','PL':pl||'ทั้งหมด','บุคลากรในฐานติดตาม':a.people,'คนที่มีเกณฑ์':a.eligible,'สมรรถนะสำเร็จ':a.complete,'สมรรถนะตามเกณฑ์':a.total,'ความก้าวหน้า (%)':+pct(a.pct),'คนที่พัฒนาครบ':a.finished,'คนที่ยังไม่ครบ':a.pending}]],['รายทักษะ',HUB_SKILLS.map((name,i)=>{const s=hubSkillSummary('core',i);return{'ทักษะ':name,'ตามเกณฑ์':s.eligible,'สำเร็จ':s.complete,'ยังขาด':s.pending,'มีแผน':s.planned,'ยังไม่มีแผน':s.unplanned,'% สำเร็จ':s.eligible?+pct(s.pct):'N/A'};})],['ราย BU',labs.map(l=>{const b=aggregate(arr.filter(e=>e.lab===l));return{'BU':l,'บุคลากร':b.people,'ตามเกณฑ์':b.total,'สำเร็จ':b.complete,'ยังขาด':b.remaining,'% สำเร็จ':b.total?+pct(b.pct):'N/A','คนที่ครบ':b.finished,'คนที่ยังไม่ครบ':b.pending};})]],`TA_Learning_Report_${year}.xlsx`);}
exportData=function(){if(tab==='reports')hubExportReport();else if(tab==='learning'&&hubFocus)hubExportDrill();else hubLegacyExport();};
document.addEventListener('click',e=>{const sk=e.target.closest('[data-hub-skill]');if(sk){hubOpenDrill(sk.dataset.hubSkill,sk.dataset.domain||'core',sk.dataset.startStatus||'pending');return;}const d=e.target.closest('[data-hub-domain]');if(d){hubDomain=d.dataset.hubDomain;hubFocus=null;renderContent();return;}const st=e.target.closest('[data-hub-status]');if(st){hubStatus=st.dataset.hubStatus;hubPage=0;renderContent();return;}const bu=e.target.closest('[data-hub-bu]');if(bu){if(bu.dataset.skillIndex!==undefined)hubFocus={kind:'core',i:+bu.dataset.skillIndex};lab=bu.dataset.hubBu;hubStatus=bu.dataset.hubBuStatus||'pending';hubPage=0;tab='learning';shell();return;}const rb=e.target.closest('[data-hub-registry-bu]');if(rb){setPersonnelBU(rb.dataset.hubRegistryBu);tab='peopleDB';shell();return;}const ps=e.target.closest('[data-hub-person-status]');if(ps){lab=ps.dataset.buValue;status=ps.dataset.hubPersonStatus;tab='directory';page=0;shell();return;}const per=e.target.closest('[data-hub-person]');if(per){hubProfile(per.dataset.hubPerson);return;}const pe=e.target.closest('[data-profile-edit]');if(pe){openPersonnelDialog(pe.dataset.profileEdit);return;}const psk=e.target.closest('[data-profile-skill]');if(psk){$('#detail').close();hubOpenDrill(psk.dataset.profileSkill,psk.dataset.domain,'all');return;}const pg=e.target.closest('[data-hub-page]');if(pg){hubPage=Math.max(0,hubPage+Number(pg.dataset.hubPage));renderContent();return;}const a=e.target.closest('[data-hub]')?.dataset.hub;if(!a)return;if(a==='back-skills'){hubFocus=null;hubDrillSearch='';renderContent();}if(a==='all-bu'){lab='';hubPage=0;shell();}if(a==='registry'){dbBU=lab;tab='peopleDB';shell();}if(a==='skills'){hubFocus=null;tab='learning';shell();}if(a==='reports'){switchMainMenu('reports');shell();}if(a==='pending'){status='pending';tab='followup';page=0;shell();}if(a==='completed'){status='done';tab='directory';page=0;shell();}if(a==='reset'){lab='';pl='';query='';if(tab==='peopleDB')resetPersonnelFilters();hubPage=0;shell();}if(a==='export-drill'){try{hubExportDrill();}catch(err){toast(err.message);}}if(a==='export-report'){try{hubExportReport();}catch(err){toast(err.message);}}if(a==='print')window.print();if(a==='connection'||a==='account'){tab='guide';shell();}window.scrollTo(0,0);});
const HUB_PL_ORDER=['PL 5','PL 4','PL 3','PL 2','PL 1'];
const HUB_ROLE_LABEL={'PL 5':'ผู้อำนวยการ','PL 4':'รองผู้อำนวยการ','PL 3':'ผู้จัดการฝ่าย / นักวิทยาศาสตร์ชำนาญการ','PL 2':'ผู้จัดการแผนก / นักวิทยาศาสตร์อาวุโส','PL 1':'พนักงาน / นักวิทยาศาสตร์'};
function hubRosterCount(level,onlyActive=false){return records.filter(e=>(!onlyActive||active(e))&&e.pl===level).length;}
function hubCompetencyConnection(){return `<section class="panel hub-model-panel"><div class="panel-head"><div><h3>6 Competency Model เชื่อมกับรายชื่อจริง</h3><p>สีเขียวมรกต = Must Have · สีแชมเปญ = Should Have · คลิกช่องสีเพื่อเปิดรายชื่อและผลพัฒนาของ PL นั้น</p></div><span class="badge">SOURCE 2 × SKILL RESULTS</span></div><div class="table-wrap"><table class="model-table"><colgroup><col class="model-name-col"><col span="5" class="model-pl-col"></colgroup><thead><tr><th>Competency</th>${HUB_PL_ORDER.map(p=>`<th>${p}<small>${HUB_ROLE_LABEL[p].replace(" / "," /<br> ")}</small></th>`).join('')}</tr></thead><tbody>${HUB_SKILLS.map((n,i)=>`<tr><td><span>${i+1}</span><strong>${n}</strong></td>${HUB_PL_ORDER.map(p=>{const r=MATRIX[p],kind=r.must.includes(i+1)?'must':r.should.includes(i+1)?'should':'';return `<td>${kind?`<button class="model-cell ${kind}" data-model-skill="${i}" data-model-pl="${p}"><b>${kind==='must'?'Must':'Should'}</b><small>${hubRosterCount(p,true)} คนในฐานติดตาม</small></button>`:'<span class="model-none">—</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="model-legend"><span><i class="must"></i> Must Have: ทักษะที่จำเป็นต้องมี</span><span><i class="should"></i> Should Have: ทักษะที่ควรต้องมี</span></div></section>`;}
hubExportReport=function(){
  const arr=selectData(),a=aggregate(arr),labs=[...new Set(arr.map(e=>e.lab))];
  const model=HUB_SKILLS.map((name,i)=>{
    const row={'ลำดับ':i+1,'Competency':name};
    HUB_PL_ORDER.forEach(p=>row[p]=MATRIX[p].must.includes(i+1)?'Must Have':MATRIX[p].should.includes(i+1)?'Should Have':'—');
    return row;
  });
  hubDownloadWorkbook([
    ['สรุป',[{'ปี':+year,'BU':lab||'ทั้งหมด','PL':pl||'ทั้งหมด','รายชื่อในทะเบียน':records.length,'บุคลากรในฐานติดตาม':a.people,'คนที่มีเกณฑ์':a.eligible,'สมรรถนะสำเร็จ':a.complete,'สมรรถนะตามเกณฑ์':a.total,'ความก้าวหน้า (%)':+pct(a.pct),'คนที่พัฒนาครบ':a.finished,'คนที่ยังไม่ครบ':a.pending}]],
    ['6 Competency Model',model],
    ['รายทักษะ',HUB_SKILLS.map((name,i)=>{const s=hubSkillSummary('core',i);return{'ทักษะ':name,'ตามเกณฑ์':s.eligible,'สำเร็จ':s.complete,'ยังขาด':s.pending,'มีแผน':s.planned,'ยังไม่มีแผน':s.unplanned,'% สำเร็จ':s.eligible?+pct(s.pct):'N/A'};})],
    ['ราย BU',labs.map(l=>{const b=aggregate(arr.filter(e=>e.lab===l));return{'BU':l,'บุคลากร':b.people,'ตามเกณฑ์':b.total,'สำเร็จ':b.complete,'ยังขาด':b.remaining,'% สำเร็จ':b.total?+pct(b.pct):'N/A','คนที่ครบ':b.finished,'คนที่ยังไม่ครบ':b.pending};})]
  ],`TA_Learning_Report_${year}.xlsx`);
};
const hubReportsConnected=hubReports;
hubReports=function(){return hubReportsConnected().replace('<section class="panel"><div class="panel-head"><div><h3>ผลพัฒนารายทักษะ',hubCompetencyConnection()+'<section class="panel"><div class="panel-head"><div><h3>ผลพัฒนารายทักษะ');};
document.addEventListener('click',e=>{const model=e.target.closest('[data-model-skill]');if(model){pl=model.dataset.modelPl;hubOpenDrill(model.dataset.modelSkill,'core','all');return;}});
// Expand-on-click learning map. Each branch uses the same filtered people as reports.
let learningMapOpen=new Set(),learningMapSelected='',learningMapFilter='all',learningMapZoom=1;
const learningMapModes=[{name:'แยกตามแล็บ',fields:['lab','pl','title'],color:'peach',graphic:2},{name:'แยกตาม PL',fields:['pl','lab','title'],color:'blue',graphic:0},{name:'แยกตามตำแหน่ง',fields:['title','lab','pl'],color:'violet',graphic:4}];
function lmGroupValue(e,field){const raw=String(e[field]||'ไม่ระบุ');return field==='title'?raw.trim().replace(/\s+/g,' ').replace(/\s*\(\s*/g,' (').replace(/\s*\)/g,')').replace(/\s*&\s*/g,' & '):raw;}
const learningMapLabels={lab:'แล็บ',pl:'ระดับ PL',title:'ตำแหน่ง'};
function learningMapStats(rows){const complete=rows.filter(x=>x.complete).length;return `<span class="lm-stats"><span>สำเร็จ <b>${complete}</b></span><span>ยังขาด <b>${rows.length-complete}</b></span></span>`;}
function learningMapKey(parts){return encodeURIComponent(JSON.stringify(parts));}
function learningMapGroup(rows,mode,depth,path){
  if(depth===mode.fields.length)return rows.map(x=>`<li class="lm-item"><button class="lm-node lm-person lm-level-6 ${x.complete?'finished':'waiting'}" data-lm-level="6" data-hub-person="${esc(x.e.id)}" data-lm-path="${learningMapKey(path)}"><span class="lm-avatar">${esc(x.e.firstName.slice(0,1))}</span><span><strong>${esc(x.e.firstName+' '+x.e.lastName)}</strong><small>${esc(x.e.lab)} · ${esc(x.e.pl)}</small><span class="lm-person-status">${x.complete?'✓ สำเร็จแล้ว':x.planned?'◷ มีแผนพัฒนา':'◷ ยังไม่มีแผน'}</span></span>${icon('arrow')}</button></li>`).join('');
  const field=mode.fields[depth],groups=[...new Set(rows.map(x=>lmGroupValue(x.e,field)))].sort((a,b)=>a.localeCompare(b,'th'));
  return groups.map(value=>{const list=rows.filter(x=>(lmGroupValue(x.e,field))===value),parts=[...path,value],key=learningMapKey(parts),open=learningMapOpen.has(key);return `<li class="lm-item"><button class="lm-node lm-level-${depth+3} ${list.some(x=>!x.complete)?'lm-needs-work':''} ${learningMapSelected===key?'selected':''}" data-lm-level="${depth+3}" data-lm-toggle="${key}" aria-expanded="${open}"><span class="lm-node-icon">${icon(field==='lab'?'briefcase':field==='pl'?'layers':'users')}</span><span class="lm-node-copy"><small>${learningMapLabels[field]}</small><strong>${esc(value)}</strong>${learningMapStats(list)}</span><span class="lm-expand">${open?'−':'+'}</span></button>${open?`<ul class="lm-children">${learningMapGroup(list,mode,depth+1,parts)}</ul>`:''}</li>`;}).join('');
}
const learningMapOldCard=hubSkillCard;
hubSkillCard=function(i,kind='core'){const s=hubSkillSummary(kind,i);return learningMapOldCard(i,kind).replace('<span class="skill-progress">',`<span class="lm-card-total">${kind==='core'?'ต้องพัฒนาตามเกณฑ์':'มีรายการเรียน'} <b>${s.eligible}</b> คน</span><span class="skill-progress">`);};
const learningMapOldOpen=hubOpenDrill;
hubOpenDrill=function(i,kind='core',view='all'){learningMapOpen=new Set();learningMapSelected='';learningMapFilter='all';learningMapZoom=1;lmPersonId='';lmOverviewFit=true;lmTableFilter='all';lmColumnFilters={};lmCloseSearch();learningMapOldOpen(i,kind,view);};
hubDrillView=function(){
  const {kind,i}=hubFocus,s=hubSkillSummary(kind,i),all=s.people.filter(x=>x.required),rows=all.filter(x=>learningMapFilter==='all'||(learningMapFilter==='done'?x.complete:!x.complete)),rootOpen=learningMapOpen.has('root'),title=kind==='core'?HUB_SKILLS[i]:upNames()[i];
  return `<div class="lm-toolbar"><button class="hub-back" data-hub="back-skills">← กลับไปเลือกทักษะ</button><div class="lm-filters">${[['all','ทั้งหมด',all.length],['done','สำเร็จ',s.complete],['pending',kind==='up'?'ยังไม่ครบ':'ยังขาด',s.pending]].map(([key,label,n])=>`<button data-lm-filter="${key}" class="${learningMapFilter===key?'active':''}" aria-pressed="${learningMapFilter===key}">${label} <b>${n}</b></button>`).join('')}</div><button class="btn" data-lm-collapse>ยุบทั้งหมด</button></div><div class="lm-intro"><span class="eyebrow">${kind==='core'?'สมรรถนะหลัก':'หลักสูตร Upskilling'}</span><h2>${esc(title)}</h2><p>คลิกการ์ดเพื่อแตกกิ่ง · เปิดได้หลายกิ่งพร้อมกัน · คลิกซ้ำเพื่อยุบ</p></div><section class="lm-canvas" aria-label="แผนผังทักษะแบบขยายได้"><div class="lm-scroll" tabindex="0"><div class="lm-tree" style="zoom:${learningMapZoom}"><ul class="lm-root-list"><li class="lm-item"><button class="lm-node lm-root lm-level-1 ${learningMapSelected==='root'?'selected':''}" data-lm-level="1" data-lm-toggle="root" aria-expanded="${rootOpen}">${hubSkillGraphic(kind,i)}<strong>${esc(title)}</strong><span class="lm-root-total">${kind==='core'?'ต้องพัฒนาตามเกณฑ์':'มีรายการเรียน'}<b>${s.eligible} คน</b></span>${learningMapStats(all)}<span class="lm-root-hint">${rootOpen?'− คลิกเพื่อยุบกิ่ง':'+ คลิกเพื่อสำรวจ'}</span></button>${rootOpen?`<ul class="lm-children lm-modes">${learningMapModes.map((mode,index)=>{const key=learningMapKey([index]),open=learningMapOpen.has(key);return `<li class="lm-item ${mode.color}"><button class="lm-node lm-mode lm-level-2 ${learningMapSelected===key?'selected':''}" data-lm-level="2" data-lm-toggle="${key}" aria-expanded="${open}">${hubTopicGraphic(HUB_ART.group[index])}<span><strong>${mode.name}</strong><small>${rows.length} คนในมุมมองนี้</small></span><span class="lm-expand">${open?'−':'+'}</span></button>${open?`<ul class="lm-children">${learningMapGroup(rows,mode,0,[index])||'<li class="lm-empty">ไม่มีบุคลากรในสถานะนี้</li>'}</ul>`:''}</li>`;}).join('')}</ul>`:''}</li></ul></div></div><div class="lm-bottom"><span>${rootOpen?'เลื่อนแนวนอนเพื่อดูกิ่งที่ขยาย · แต่ละมุมมองเป็นบุคลากรชุดเดียวกัน ไม่นำยอดมาบวกกัน':'เริ่มจากคลิกการ์ดทักษะ แล้วเลือกกิ่งที่ต้องการดู'}</span><div class="lm-zoom"><button data-lm-zoom="-0.1" aria-label="ย่อแผนผัง">−</button><b>${Math.round(learningMapZoom*100)}%</b><button data-lm-zoom="0.1" aria-label="ขยายแผนผัง">+</button><button data-lm-reset>100%</button></div></div></section>`;
};
function learningMapRefresh(){const viewport=$('.lm-scroll'),left=viewport?.scrollLeft||0,top=viewport?.scrollTop||0;renderContent();const next=$('.lm-scroll');if(next){next.scrollLeft=left;next.scrollTop=top;}}
document.addEventListener('click',e=>{
  const toggle=e.target.closest('[data-lm-toggle]');if(toggle){const key=toggle.dataset.lmToggle;learningMapSelected=key;if(learningMapOpen.has(key)){learningMapOpen.delete(key);if(key==='root')learningMapOpen.clear();else{const path=JSON.parse(decodeURIComponent(key));for(const other of [...learningMapOpen])if(other!=='root'){const p=JSON.parse(decodeURIComponent(other));if(p.length>path.length&&path.every((v,i)=>v===p[i]))learningMapOpen.delete(other);}}}else learningMapOpen.add(key);learningMapRefresh();return;}
  const filter=e.target.closest('[data-lm-filter]');if(filter){learningMapFilter=filter.dataset.lmFilter;learningMapRefresh();return;}
  if(e.target.closest('[data-lm-collapse]')){learningMapOpen.clear();learningMapSelected='';learningMapRefresh();return;}
  const zoom=e.target.closest('[data-lm-zoom]');if(zoom){learningMapZoom=Math.max(.2,Math.min(5,Math.round((learningMapZoom+Number(zoom.dataset.lmZoom))*10)/10));learningMapRefresh();return;}
  if(e.target.closest('[data-lm-reset]')){learningMapZoom=1;learningMapRefresh();}
});
// Fit the complete expanded tree; keep readable detail in the linked table.
let lmPersonId='',lmOverviewFit=true,lmTableFilter='all';
function lmSelectedRows(ignoreStatus=false){
 const s=hubSkillSummary(hubFocus.kind,hubFocus.i);let rows=s.people.filter(x=>x.required),labels=[];
 if(learningMapSelected&&learningMapSelected!=='root'){
 const parts=JSON.parse(decodeURIComponent(learningMapSelected)),mode=learningMapModes[parts[0]];
 labels=[mode.name,...parts.slice(1)];parts.slice(1).forEach((v,j)=>{rows=rows.filter(x=>lmGroupValue(x.e,mode.fields[j])===v);});
 }
 if(!ignoreStatus)rows=rows.filter(x=>learningMapFilter==='all'||(learningMapFilter==='done'?x.complete:!x.complete));
 if(lmPersonId)rows=rows.filter(x=>String(x.e.id)===lmPersonId);
 return {rows,labels};
}
let lmColumnFilters={};
function lmFilterValues(key){const v=lmColumnFilters[key];return Array.isArray(v)?v:v?[v]:null;}
function lmFilterLabel(key){const values=lmFilterValues(key);return values===null?'ทั้งหมด':values.length===1?values[0]:`เลือก ${values.length} รายการ`;}
let lmSearchDraft=new Set();

const lmTableColumns=[['name','ชื่อ–นามสกุล'],['lab','แล็บ / BU'],['pl','PL'],['title','ตำแหน่ง'],['kind','เกณฑ์'],['result','ผลพัฒนา']];
function lmTableValue(x,key){return String(key==='name'?x.e.firstName+' '+x.e.lastName:key==='kind'?x.kind:key==='result'?(x.complete?'สำเร็จ':x.planned?'ยังไม่ครบ · มีแผน':'ยังไม่ครบ · ยังไม่มีแผน'):x.e[key]||'ไม่ระบุ');}
function lmTableRows(){return lmSelectedRows(true).rows.filter(x=>(lmTableFilter==='all'||(lmTableFilter==='done'?x.complete:!x.complete))&&lmTableColumns.every(([key])=>lmFilterValues(key)===null||lmFilterValues(key).includes(lmTableValue(x,key)))).sort((a,b)=>Number(a.complete)-Number(b.complete));}
function lmTableHead(all){return lmTableColumns.map(([key,label])=>`<th scope="col"><span>${label}</span><button class="lm-filter-trigger ${lmFilterValues(key)!==null?'is-filtered':''}" data-lm-search-open="${key}" aria-label="กรอง${label}" aria-haspopup="dialog" aria-expanded="false"><span>${esc(lmFilterLabel(key))}</span><span>⌄</span></button></th>`).join('');}
function lmSearchValues(key,query=''){const q=query.trim().toLocaleLowerCase('th');return [...new Set(lmSelectedRows(true).rows.map(x=>lmTableValue(x,key)))].filter(value=>value.toLocaleLowerCase('th').includes(q)).sort((a,b)=>a.localeCompare(b,'th'));}
let lmSearchTrigger=null;
function lmCloseSearch(restore=false){document.querySelector('.lm-search-popup')?.remove();lmSearchTrigger?.setAttribute('aria-expanded','false');if(restore)lmSearchTrigger?.focus();lmSearchTrigger=null;}
function lmSearchOptions(key,query){const values=lmSearchValues(key,query);return values.map(value=>`<label class="lm-search-option ${lmSearchDraft.has(value)?'chosen':''}"><input type="checkbox" data-lm-check="${esc(value)}" ${lmSearchDraft.has(value)?'checked':''}><span>${esc(value)}</span></label>`).join('')||'<p class="lm-search-empty">ไม่พบรายการที่ค้นหา</p>';}
function lmUpdateDraftCount(){const popup=document.querySelector('.lm-search-popup');if(!popup)return;popup.querySelector('[data-lm-selected-count]').textContent=`เลือก ${lmSearchDraft.size} รายการ`;const all=popup.querySelector('[data-lm-check-all]'),total=lmSearchValues(all.dataset.lmCheckAll).length;all.checked=lmSearchDraft.size===total;all.indeterminate=lmSearchDraft.size>0&&lmSearchDraft.size<total;popup.querySelector('[data-lm-apply]').disabled=!lmSearchDraft.size;}
function lmOpenSearch(button){const wasOpen=lmSearchTrigger===button;lmCloseSearch();if(wasOpen)return;lmSearchTrigger=button;const key=button.dataset.lmSearchOpen,label=lmTableColumns.find(x=>x[0]===key)[1],popup=document.createElement('div');popup.className='lm-search-popup';popup.setAttribute('role','dialog');popup.setAttribute('aria-label','ค้นหา'+label);lmSearchDraft=new Set(lmFilterValues(key)||lmSearchValues(key));popup.innerHTML=`<div class="lm-search-input-wrap"><input type="search" data-lm-search-query="${key}" placeholder="พิมพ์ค้นหา${label}…" aria-label="ค้นหา${label}" autocomplete="off"></div><label class="lm-search-all"><input type="checkbox" data-lm-check-all="${key}"> เลือกทั้งหมด</label><div class="lm-search-options">${lmSearchOptions(key,'')}</div><div class="lm-search-footer"><span data-lm-selected-count></span><button type="button" data-lm-apply="${key}">ใช้ตัวกรอง</button></div>`;document.body.append(popup);lmUpdateDraftCount();button.setAttribute('aria-expanded','true');const rect=button.getBoundingClientRect(),width=Math.min(Math.max(rect.width,320),window.innerWidth-24);popup.style.width=width+'px';popup.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-width-12))+'px';const desired=Math.min(540,window.innerHeight-24),below=window.innerHeight-rect.bottom-18,above=rect.top-18;let top;if(below>=desired)top=rect.bottom+6;else if(above>=desired)top=rect.top-desired-6;else top=Math.max(12,Math.min(rect.bottom+6,window.innerHeight-desired-12));popup.style.top=top+'px';popup.style.height=desired+'px';popup.style.maxHeight='calc(100dvh - 24px)';popup.querySelector('input').focus();}
function lmTableExportRows(){return lmTableRows().map(x=>({...Object.fromEntries(lmTableColumns.map(([key,label])=>[label,lmTableValue(x,key)])),'ทักษะ':hubFocus.kind==='core'?NAMES[hubFocus.i]:upNames()[hubFocus.i],'ผลต้นฉบับ':x.e.cells[hubFocus.i]||'','สะสมถึงปี':Number(year)}));}
function lmExportTable(){const rows=lmTableExportRows();if(!rows.length)return toast('ไม่มีรายการตามตัวกรองให้ส่งออก');const {labels}=lmSelectedRows(true);hubDownloadWorkbook([['รายชื่อที่กรอง',rows],['เงื่อนไข',[{'เส้นทาง':labels.join(' › ')||'ทั้งหมด','สถานะ':lmTableFilter==='all'?'ทั้งหมด':lmTableFilter==='done'?'สำเร็จ':'ยังไม่ครบ','จำนวนคน':rows.length,'สะสมถึงปี':Number(year),...Object.fromEntries(lmTableColumns.map(([key,label])=>[label,lmFilterValues(key)?.join(' / ')||'ทั้งหมด']))}]]],`TA_Learning_Filtered_${year}.xlsx`);}
function lmDetailTable(){const {rows:all,labels}=lmSelectedRows(true),complete=all.filter(x=>x.complete).length,rows=lmTableRows();return `<section class="panel lm-details"><div class="panel-head"><div><span class="eyebrow">SELECTED BRANCH</span><h3>${labels.length?esc(labels.join(' › ')):'บุคลากรทั้งหมดในทักษะนี้'}</h3><p>${rows.length} คน · ${learningMapStats(rows)} · สะสมถึงปี ${esc(year)}</p></div><div class="lm-table-actions"><span class="lm-linked">● เชื่อมกับกิ่งที่เลือก</span><button class="btn lm-export" data-lm-export ${rows.length?'':'disabled'}>${icon('export')}<span>Export Excel</span><b class="lm-export-count">${rows.length} คน</b></button></div></div><div class="lm-table-filters" role="group" aria-label="กรองสถานะในตาราง">${[['all','ทั้งหมด',all.length],['done','สำเร็จ',complete],['pending','ยังไม่ครบ',all.length-complete]].map(([key,label,n])=>`<button data-lm-table-filter="${key}" class="${lmTableFilter===key?'active':''}" aria-pressed="${lmTableFilter===key}">${label} <b>${n}</b></button>`).join('')}<button class="filter-reset" data-lm-clear-columns><span class="filter-reset-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/></svg></span><span>ล้างตัวกรองทั้งหมด</span></button><span>แสดง ${rows.length} จาก ${all.length} คนในกิ่งนี้</span></div><div class="table-wrap"><table><thead><tr>${lmTableHead(all)}</tr></thead><tbody>${rows.map(x=>`<tr class="${x.complete?'lm-complete-row':'lm-pending-row'}"><td><button class="person-open" data-hub-person="${esc(x.e.id)}">${esc(x.e.firstName+' '+x.e.lastName)}</button></td><td>${esc(x.e.lab)}</td><td>${esc(x.e.pl)}</td><td>${esc(x.e.title)}</td><td>${esc(x.kind)}</td><td><span class="status ${x.complete?'done':'lm-incomplete'}">${x.complete?'✓ สำเร็จ':x.planned?'● ยังไม่ครบ · มีแผน':'● ยังไม่ครบ · ยังไม่มีแผน'}</span><small class="lm-raw">${esc(x.e.cells[hubFocus.i]||'ยังไม่ระบุ')}</small></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ไม่มีบุคลากรตรงกับกิ่งและสถานะที่เลือก</td></tr>'}</tbody></table></div></section>`;}
const lmOriginalDrill=hubDrillView;
hubDrillView=function(){return lmOriginalDrill().replace(/data-hub-person=/g,'data-lm-person=').replace('เลื่อนแนวนอนเพื่อดูกิ่งที่ขยาย · แต่ละมุมมองเป็นบุคลากรชุดเดียวกัน ไม่นำยอดมาบวกกัน','คลิกบล็อกเพื่อเลือกหรือขยาย · กดค้างแล้วลากเพื่อเลื่อน · ลูกกลิ้งเมาส์เพื่อซูม').replace('<button data-lm-reset>100%</button>','<button data-lm-fit>พอดีจอ</button>')+lmDetailTable();};
function lmFit(){
 const viewport=document.querySelector('.lm-scroll'),tree=document.querySelector('.lm-tree');if(!viewport||!tree)return;
 let stage=viewport.querySelector('.lm-stage');if(!stage){stage=document.createElement('div');stage.className='lm-stage';viewport.append(stage);stage.append(tree);}
 tree.style.zoom='1';tree.style.transform='none';tree.style.left='0';tree.style.top='0';tree.querySelector('.lm-wires')?.remove();tree.querySelectorAll('.lm-selection-glow').forEach(el=>el.remove());
 
 const selected=lmPersonId?tree.querySelector(`[data-lm-person="${CSS.escape(lmPersonId)}"]`):tree.querySelector(`[data-lm-toggle="${CSS.escape(learningMapSelected)}"],[data-lm-table="${CSS.escape(learningMapSelected)}"]`),ancestors=new Set();
 let current=selected?.closest('.lm-item');while(current){ancestors.add(current);current=current.parentElement?.closest('.lm-item');}
 tree.querySelectorAll('.lm-node').forEach(node=>{const onPath=ancestors.has(node.closest('.lm-item')),isCurrent=node===selected;node.classList.toggle('lm-route',onPath);node.classList.toggle('lm-current-node',isCurrent);node.classList.toggle('lm-outside-route',!!selected&&!onPath);node.querySelector('.lm-selection-label')?.remove();if(onPath){const badge=document.createElement('span');badge.className='lm-selection-label';badge.textContent=isCurrent?'● กำลังเลือก':node.classList.contains('lm-root')?'จุดเริ่มต้นที่เลือก':'เส้นทางที่เลือก';node.append(badge);}if(isCurrent)node.setAttribute('aria-current','true');else node.removeAttribute('aria-current');});
 tree.querySelectorAll('[data-lm-level]').forEach(node=>{if(!node.querySelector('.lm-level-tag')){const tag=document.createElement('span');tag.className='lm-level-tag';tag.textContent='ชั้น '+node.dataset.lmLevel;node.append(tag);}});
 tree.classList.remove('lm-compact-fit');if(tree.scrollWidth>viewport.clientWidth-24||tree.scrollHeight>viewport.clientHeight-24)tree.classList.add('lm-compact-fit');
 // Try several group widths and retain the arrangement with the largest readable scale.
 let bestColumns=1,bestFit=-1;
 for(let columns=1;columns<=4;columns++){tree.style.setProperty('--lm-columns',columns);const candidate=Math.min(1,(viewport.clientWidth-24)/tree.scrollWidth,(viewport.clientHeight-24)/tree.scrollHeight);if(candidate>bestFit+.001){bestFit=candidate;bestColumns=columns;}}
 tree.style.setProperty('--lm-columns',bestColumns);
 tree.querySelectorAll('.lm-selection-glow').forEach(el=>el.remove());
 if(selected){const ns='http://www.w3.org/2000/svg',glow=document.createElementNS(ns,'svg'),ring=document.createElementNS(ns,'rect');glow.setAttribute('class','lm-selection-glow');glow.setAttribute('aria-hidden','true');glow.setAttribute('width',selected.clientWidth+24);glow.setAttribute('height',selected.clientHeight+24);ring.setAttribute('x','3');ring.setAttribute('y','3');ring.setAttribute('width',selected.clientWidth+18);ring.setAttribute('height',selected.clientHeight+18);ring.setAttribute('rx','24');ring.setAttribute('pathLength','100');const track=ring.cloneNode();track.setAttribute('class','lm-glow-track');ring.setAttribute('class','lm-glow-runner');glow.append(track,ring);selected.append(glow);}

 const w=tree.scrollWidth,h=tree.scrollHeight,fit=Math.min(1,(viewport.clientWidth-24)/w,(viewport.clientHeight-24)/h),scale=(lmOverviewFit?fit:Math.max(.7,fit))*learningMapZoom;
 stage.style.width=Math.max(viewport.clientWidth,w*scale+24)+'px';stage.style.height=Math.max(viewport.clientHeight,h*scale+24)+'px';
 tree.dataset.scale=scale;tree.style.transform=`scale(${scale})`;tree.style.left='12px';tree.style.top=`${Math.max(12,(viewport.clientHeight-h*scale)/2)}px`;
 const box=tree.getBoundingClientRect(),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.classList.add('lm-wires');svg.setAttribute('width',w);svg.setAttribute('height',h);
 tree.querySelectorAll('.lm-children>.lm-item').forEach(item=>{const child=item.querySelector(':scope>.lm-node'),parent=item.parentElement.closest('.lm-item')?.querySelector(':scope>.lm-node');if(!child||!parent)return;const a=parent.getBoundingClientRect(),b=child.getBoundingClientRect(),x1=(a.right-box.left)/scale,y1=(a.top+a.height/2-box.top)/scale,x2=(b.left-box.left)/scale,y2=(b.top+b.height/2-box.top)/scale,mid=(x1+x2)/2;const group=item.parentElement,groupBox=group.getBoundingClientRect(),grid=!group.classList.contains('lm-modes'),gutter=(groupBox.left-box.left)/scale-20,entryX=(b.left+b.width/2-box.left)/scale,entryY=(b.top-box.top)/scale,lane=(item.getBoundingClientRect().top-box.top)/scale-25,d=grid?`M${x1},${y1} H${gutter} V${lane} H${entryX} V${entryY}`:`M${x1},${y1} H${mid} V${y2} H${x2}`;
 const p=document.createElementNS(ns,'path');p.setAttribute('d',d);p.setAttribute('class','lm-wire'+(ancestors.has(item)?' focus':''));svg.append(p);if(ancestors.has(item)){const light=p.cloneNode();light.setAttribute('class','lm-current');svg.append(light);}
 });tree.querySelectorAll('.lm-item:has(>.lm-children)').forEach(item=>{const parent=item.querySelector(':scope>.lm-node'),child=item.querySelector(':scope>.lm-children>.lm-item>.lm-node');if(!parent||!child)return;const a=parent.getBoundingClientRect(),b=child.getBoundingClientRect(),dot=document.createElementNS(ns,'circle');const group=item.querySelector(':scope>.lm-children');dot.setAttribute('cx',group.classList.contains('lm-modes')?((a.right+b.left)/2-box.left)/scale:(group.getBoundingClientRect().left-box.left)/scale-20);dot.setAttribute('cy',(a.top+a.height/2-box.top)/scale);dot.setAttribute('r','5');dot.setAttribute('class','lm-junction'+(ancestors.has(item)?' focus':''));svg.append(dot);});tree.prepend(svg);const percent=document.querySelector('.lm-zoom b');if(percent)percent.textContent=Math.round(scale*100)+'%';
}
const lmRender=renderContent;renderContent=function(){lmRender();if(tab==='learning'&&hubFocus)requestAnimationFrame(lmFit);};
// Capture selection before existing expansion handlers render the view.
document.addEventListener('click',e=>{
 if(e.target.closest('[data-hub-skill],[data-profile-skill],[data-model-skill],[data-lm-toggle],[data-lm-table],[data-lm-collapse]')){lmPersonId='';lmOverviewFit=true;learningMapZoom=1;lmTableFilter='all';lmColumnFilters={};requestAnimationFrame(viewportReset);}
 const terminal=e.target.closest('[data-lm-table]');if(terminal){learningMapSelected=terminal.dataset.lmTable;renderContent();requestAnimationFrame(()=>document.querySelector('.lm-details')?.scrollIntoView({behavior:'smooth',block:'start'}));return;}
 const tf=e.target.closest('[data-lm-table-filter]');if(tf){lmTableFilter=tf.dataset.lmTableFilter;const section=document.querySelector('.lm-details');section.outerHTML=lmDetailTable();return;}
 const person=e.target.closest('[data-lm-person]');if(person){lmPersonId=person.dataset.lmPerson;learningMapSelected=person.dataset.lmPath;lmOverviewFit=true;learningMapZoom=1;lmTableFilter='all';lmColumnFilters={};renderContent();requestAnimationFrame(viewportReset);return;}
 if(e.target.closest('[data-lm-fit]')){lmOverviewFit=true;learningMapZoom=1;lmFit();viewportReset();}
 if(e.target.closest('[data-lm-zoom]'))lmOverviewFit=true;
},true);
function viewportReset(){const v=document.querySelector('.lm-scroll');if(v){v.scrollTop=0;v.scrollLeft=0;}}
window.addEventListener('resize',()=>requestAnimationFrame(lmFit));
if(document.fonts)document.fonts.ready.then(()=>requestAnimationFrame(lmFit));


let lmDrag=null,lmIgnoreClick=false,lmIgnoreUntil=0;
function lmZoomAt(viewport,factor,clientX,clientY){
 const tree=viewport.querySelector('.lm-tree'),r=viewport.getBoundingClientRect(),oldScale=Number(tree.dataset.scale)||1,old=tree.getBoundingClientRect(),x=clientX-r.left,y=clientY-r.top,worldX=(clientX-old.left)/oldScale,worldY=(clientY-old.top)/oldScale;
 lmOverviewFit=true;learningMapZoom=Math.max(.2,Math.min(5,learningMapZoom*factor));lmFit();
 const newScale=Number(tree.dataset.scale)||1;viewport.scrollLeft=parseFloat(tree.style.left)+worldX*newScale-x;viewport.scrollTop=parseFloat(tree.style.top)+worldY*newScale-y;
}
document.addEventListener('wheel',e=>{const v=e.target.closest('.lm-scroll');if(!v)return;e.preventDefault();lmZoomAt(v,Math.exp(-Math.max(-120,Math.min(120,e.deltaY))*.0025),e.clientX,e.clientY);},{passive:false});
// Click remains native until a deliberate drag crosses the movement threshold.
document.addEventListener('pointerdown',e=>{
 const v=e.target.closest('.lm-scroll');if(!v||e.button!==0||lmDrag)return;
 lmIgnoreClick=false;
 lmDrag={v,id:e.pointerId,x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop,moved:false};
});
document.addEventListener('pointermove',e=>{
 const d=lmDrag;if(!d||e.pointerId!==d.id)return;
 const dx=e.clientX-d.x,dy=e.clientY-d.y;
 if(!d.moved){if(Math.hypot(dx,dy)<6)return;d.moved=true;d.v.setPointerCapture(d.id);d.v.classList.add('lm-dragging');}
 e.preventDefault();d.v.scrollLeft=d.left-dx;d.v.scrollTop=d.top-dy;
});
function lmEndDrag(e){
 const d=lmDrag;if(!d||(e&&e.pointerId!==d.id))return;
 lmIgnoreClick=d.moved;lmIgnoreUntil=Date.now()+500;
 d.v.classList.remove('lm-dragging');lmDrag=null;
 if(d.v.hasPointerCapture?.(d.id))d.v.releasePointerCapture(d.id);
}
document.addEventListener('pointerup',lmEndDrag);document.addEventListener('pointercancel',lmEndDrag);
document.addEventListener('lostpointercapture',lmEndDrag);
window.addEventListener('click',e=>{
 if(lmIgnoreClick&&Date.now()<lmIgnoreUntil&&e.target.closest('.lm-scroll')){
  lmIgnoreClick=false;e.preventDefault();e.stopImmediatePropagation();
 }
},true);

if(!window.TA_CLOUD?.enabled||dbReady)shell();

document.addEventListener('change',e=>{const field=e.target.closest('[data-lm-column]');if(!field)return;lmColumnFilters[field.dataset.lmColumn]=field.value;document.querySelector('.lm-details').outerHTML=lmDetailTable();});
document.addEventListener('click',e=>{if(e.target.closest('[data-lm-export]')){try{lmExportTable();}catch(error){toast('ส่งออกไม่สำเร็จ: '+error.message);}}if(e.target.closest('[data-lm-clear-columns]')){lmColumnFilters={};lmTableFilter='all';document.querySelector('.lm-details').outerHTML=lmDetailTable();}});

document.addEventListener('click',e=>{const trigger=e.target.closest('[data-lm-search-open]');if(trigger){lmOpenSearch(trigger);return;}const apply=e.target.closest('[data-lm-apply]');if(apply){const key=apply.dataset.lmApply;lmColumnFilters[key]=lmSearchDraft.size===lmSearchValues(key).length?null:[...lmSearchDraft];lmCloseSearch();document.querySelector('.lm-details').outerHTML=lmDetailTable();document.querySelector(`[data-lm-search-open="${key}"]`)?.focus();return;}if(!e.target.closest('.lm-search-popup'))lmCloseSearch();});
document.addEventListener('input',e=>{const input=e.target.closest('[data-lm-search-query]');if(input)input.closest('.lm-search-popup').querySelector('.lm-search-options').innerHTML=lmSearchOptions(input.dataset.lmSearchQuery,input.value);});
document.addEventListener('keydown',e=>{const popup=document.querySelector('.lm-search-popup');if(!popup)return;if(e.key==='Escape'){e.preventDefault();lmCloseSearch(true);return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){const options=[...popup.querySelectorAll('.lm-search-option input')],index=options.indexOf(document.activeElement);e.preventDefault();options[Math.max(0,Math.min(options.length-1,index+(e.key==='ArrowDown'?1:-1)))]?.focus();}if(e.key==='Tab'){const focusable=[...popup.querySelectorAll('input,button')];if((!e.shiftKey&&document.activeElement===focusable.at(-1))||(e.shiftKey&&document.activeElement===focusable[0]))lmCloseSearch(true);}});
window.addEventListener('resize',()=>lmCloseSearch());
document.addEventListener('scroll',e=>{if(!e.target.closest?.('.lm-search-popup'))lmCloseSearch();},true);

document.addEventListener('change',e=>{const check=e.target.closest('[data-lm-check]'),all=e.target.closest('[data-lm-check-all]');if(check){if(check.checked)lmSearchDraft.add(check.dataset.lmCheck);else lmSearchDraft.delete(check.dataset.lmCheck);check.closest('label').classList.toggle('chosen',check.checked);lmUpdateDraftCount();}if(all){lmSearchDraft=new Set(all.checked?lmSearchValues(all.dataset.lmCheckAll):[]);const popup=all.closest('.lm-search-popup'),query=popup.querySelector('[data-lm-search-query]');popup.querySelector('.lm-search-options').innerHTML=lmSearchOptions(all.dataset.lmCheckAll,query.value);lmUpdateDraftCount();}});
